#pragma bank 255
#include "gridduel.h"
#include <string.h>
#include "gridduel_catalog.h"
GDCard gd_cards[GD_COUNT];
GDCard *gd_card(uint8_t id) BANKED {uint8_t i;for(i=0;i<GD_COUNT;i++)if(gd_cards[i].id==id)return gd_cards+i;return gd_cards;}
uint16_t gd_atk(uint8_t i) BANKED{return gd_card(gd.inst[i].card)->atk+gd.inst[i].eq;}
uint8_t gd_attack_mask(uint8_t i) BANKED{return gd.inst[i].attack_override?gd.inst[i].attack_override:gd_card(gd.inst[i].card)->attack;}
uint8_t gd_mask(uint8_t mask,int8_t dx,int8_t dy) BANKED {if(!mask||mask>11||dx<-3||dx>3||dy<-3||dy>3)return 0;return (gd_mask_bits[mask-1][dy+3]>>(dx+3))&1;}
static uint8_t leader(uint8_t p){return gd.leader_pos[p];}
static uint8_t near(uint8_t a,uint8_t b){int8_t x=(a%7)-(b%7),y=(a/7)-(b/7);return (x==0&&(y==1||y==-1))||(y==0&&(x==1||x==-1));}
static uint8_t count(uint8_t p){uint8_t t,n=0;for(t=0;t<49;t++)if(gd.cell[t].iid!=255&&gd_owner(gd.cell[t].iid)==p&&!(gd.cell[t].flags&GD_LEADER))n++;return n;}
static void damage(uint8_t p,uint16_t v){gd.lp[p]=(gd.lp[p]<=v)?0:gd.lp[p]-v;if(!gd.lp[p]){gd.winner=1-p;gd.pane=GD_RESULT;}gd.dirty=1;}
static uint8_t draw(uint8_t p){uint8_t h;if(!gd.left[p])return 0;for(h=0;h<5;h++)if(gd.hand[p][h]==255){gd.hand[p][h]=gd.deck[p][--gd.left[p]];return 1;}return 0;}
void gd_begin(void) BANKED {uint8_t i,p,j;uint16_t seed;memcpy(gd_cards,gd_catalog,sizeof(gd_cards));memset(&gd,0,sizeof(gd));gd.pick_cell=gd.pick_hand=gd.winner=gd.info_iid=gd.reveal=255;gd.cursor=45;gd.theme[0]=script_memory[VAR_GRIDDUEL_DECK_CHOICE]==2;gd.theme[1]=1-gd.theme[0];for(i=0;i<49;i++)gd.cell[i].iid=255;
for(p=0;p<2;p++){gd.lp[p]=4000;gd.left[p]=25;for(i=0;i<25;i++){j=p*25+i;gd.inst[j].level=1;gd.inst[j].xp=0;gd.inst[j].card=gd_deck_cards[gd.theme[p]][i];gd.inst[j].eq=0;gd.inst[j].attack_override=0;gd.deck[p][i]=j;}seed=((uint16_t)DIV_REG<<8)^((uint16_t)LY_REG<<1)^(p+1);for(i=24;i>0;i--){uint8_t k,t;seed=seed*2053u+13849u;k=seed%(i+1);t=gd.deck[p][i];gd.deck[p][i]=gd.deck[p][k];gd.deck[p][k]=t;}for(i=0;i<5;i++)gd.hand[p][i]=255;for(i=0;i<5;i++)draw(p);}
/* Leaders are individual instances0/25, kept out of deck: replace their deck entries
 with same-card reserve IDs? Initial deck uses instance0 as leader; remove it from hand/deck. */
for(p=0;p<2;p++){uint8_t lid=p*25,tpos=p?3:45;for(i=0;i<5;i++)if(gd.hand[p][i]==lid)gd.hand[p][i]=255;for(i=0;i<gd.left[p];i++)if(gd.deck[p][i]==lid){gd.deck[p][i]=gd.deck[p][--gd.left[p]];break;}gd.cell[tpos].iid=lid;gd.cell[tpos].flags=GD_LEADER;gd.leader_pos[p]=tpos;draw(p);}gd.dirty=1;}
uint8_t gd_can_move(uint8_t p,uint8_t f,uint8_t t) BANKED {GDCard *c;int8_t x,y,tx,ty,dx,dy;uint8_t pos,mask;if(f>=49||t>=49||f==t||gd.cell[f].iid==255||gd_owner(gd.cell[f].iid)!=p||gd.cell[f].flags&GD_MOVED||gd.cell[t].iid!=255)return 0;c=gd_card(gd.inst[gd.cell[f].iid].card);dx=(t%7)-(f%7);dy=(t/7)-(f/7);mask=(gd.cell[f].flags&GD_LEADER)?1:c->move;if(!gd_mask(mask,dx,p?-dy:dy))return 0;if(c->jump&&!(gd.cell[f].flags&GD_LEADER))return 1;
/* Walk: canonical horizontal then vertical unit steps; every visited square checked.
 Adjacent diagonals are a single adjacent step, not a jump over another cell. */
x=f%7;y=f/7;tx=t%7;ty=t/7;if(dx>=-1&&dx<=1&&dy>=-1&&dy<=1)return 1;while(x!=tx){x+=(tx>x)?1:-1;pos=y*7+x;if(gd.cell[pos].iid!=255)return 0;}while(y!=ty){y+=(ty>y)?1:-1;pos=y*7+x;if(gd.cell[pos].iid!=255)return 0;}return 1;}
static uint8_t trap(uint8_t p,uint8_t t){uint8_t id=gd.traps[1-p][t];GDCard *c;if(!id)return 0;c=gd_card(id);gd.traps[1-p][t]=0;gd.reveal=t;gd.reveal_fx=id;gd.reveal_ticks=45;gd.msg=c->fx==3?4:5;gd.triggers++;gd.dirty=1;if(c->fx==3){if(!(gd.cell[t].flags&GD_LEADER)){gd.cell[t].iid=255;return 1;}}else damage(p,c->atk);return 0;}
static uint8_t walk_to(uint8_t p,uint8_t f,uint8_t t){gd.cell[t]=gd.cell[f];gd.cell[f].iid=255;gd.cell[t].flags=(gd.cell[t].flags|GD_MOVED)&~GD_DOWN;if(gd.cell[t].flags&GD_LEADER)gd.leader_pos[p]=t;return trap(p,t);}
uint8_t gd_move(uint8_t p,uint8_t f,uint8_t t) BANKED {GDCard *c;int8_t x,y,tx,ty;uint8_t pos,prev=f;if(!gd_can_move(p,f,t))return 0;c=gd_card(gd.inst[gd.cell[f].iid].card);gd.last_from=f;gd.last_to=t;gd.last_action=1;gd.moves++;if(c->jump||near(f,t)||((int8_t)(f%7)-(t%7)<=1&&(int8_t)(t%7)-(f%7)<=1&&(int8_t)(f/7)-(t/7)<=1&&(int8_t)(t/7)-(f/7)<=1)){walk_to(p,f,t);}else{x=f%7;y=f/7;tx=t%7;ty=t/7;while(x!=tx){x+=(tx>x)?1:-1;pos=y*7+x;if(walk_to(p,prev,pos))goto done;prev=pos;if(gd.winner!=255)goto done;}while(y!=ty){y+=(ty>y)?1:-1;pos=y*7+x;if(walk_to(p,prev,pos))goto done;prev=pos;if(gd.winner!=255)goto done;}}done:gd.dirty=1;return 1;}
uint8_t gd_can_attack(uint8_t p,uint8_t f,uint8_t t) BANKED {int8_t dx,dy;uint8_t i;if(f>=49||t>=49||f==t||gd.cell[f].iid==255||gd_owner(gd.cell[f].iid)!=p||gd.cell[f].flags&(GD_ATTACKED|GD_LEADER)||gd.cell[t].iid==255||gd_owner(gd.cell[t].iid)==p)return 0;i=gd.cell[f].iid;dx=(t%7)-(f%7);dy=(t/7)-(f/7);return gd_mask(gd_attack_mask(i),dx,p?-dy:dy);}
static uint16_t fight(uint8_t a,uint8_t b){uint8_t sa=gd_card(gd.inst[a].card)->shape,sb=gd_card(gd.inst[b].card)->shape;return gd_atk(a)+(((sa==0&&sb==2)||(sa==2&&sb==1)||(sa==1&&sb==0))?500:0);}
uint8_t gd_attack(uint8_t p,uint8_t f,uint8_t t) BANKED {uint16_t a,b;if(!gd_can_attack(p,f,t))return 0;gd.cell[f].flags=(gd.cell[f].flags|GD_ATTACKED)&~GD_DOWN;gd.cell[t].flags&=~GD_DOWN;gd.attacks++;gd.last_from=f;gd.last_to=t;gd.last_action=2;gd.msg=3;if(gd.cell[t].flags&GD_LEADER)damage(1-p,gd_atk(gd.cell[f].iid));else{a=fight(gd.cell[f].iid,gd.cell[t].iid);b=fight(gd.cell[t].iid,gd.cell[f].iid);if(a>=b)gd.cell[t].iid=255;if(b>=a)gd.cell[f].iid=255;}gd.dirty=1;return 1;}
uint8_t gd_can_play(uint8_t p,uint8_t h,uint8_t t) BANKED {GDCard*c;uint8_t i;if(h>=5||t>=49||gd.placed||gd.hand[p][h]==255)return 0;i=gd.hand[p][h];c=gd_card(gd.inst[i].card);if(c->kind==1)return 1;if(c->kind==3)return gd.cell[t].iid!=255&&gd_owner(gd.cell[t].iid)==p;if(gd.cell[t].iid!=255||!near(leader(p),t))return 0;if(c->kind==2)return !gd.traps[p][t];return count(p)<5;}
uint8_t gd_play(uint8_t p,uint8_t h,uint8_t t) BANKED {uint8_t i;GDCard*c;if(!gd_can_play(p,h,t))return 0;i=gd.hand[p][h];c=gd_card(gd.inst[i].card);gd.hand[p][h]=255;gd.placed=1;gd.msg=2;if(c->kind==1){if(c->fx==1)damage(1-p,c->atk);else gd.lp[p]=(gd.lp[p]+c->atk>4000)?4000:gd.lp[p]+c->atk;}else if(c->kind==2)gd.traps[p][t]=c->id;else if(c->kind==3){GDInstance *a=gd.inst+gd.cell[t].iid;if(c->fx==6)a->attack_override=c->attack;else{a->eq+=c->atk;if(a->eq>1500)a->eq=1500;}}else{gd.cell[t].iid=i;gd.cell[t].flags=GD_DOWN;trap(p,t);}gd.dirty=1;return 1;}
void gd_end(void) BANKED {uint8_t t,p,n=0,need=0,l;if(gd.winner!=255)return;gd.turn=1-gd.turn;p=gd.turn;gd.placed=0;gd.pick_cell=gd.pick_hand=255;gd.pane=GD_BOARD;l=leader(p);for(t=0;t<49;t++){if(near(l,t)){need++;if(gd.cell[t].iid!=255&&gd_owner(gd.cell[t].iid)!=p)n++;}if(gd.cell[t].iid!=255&&gd_owner(gd.cell[t].iid)==p)gd.cell[t].flags&=~(GD_MOVED|GD_ATTACKED);}if(need&&n==need){gd.winner=1-p;gd.pane=GD_RESULT;}else if(!gd.left[p]){gd.msg=7;damage(p,500);}else draw(p);gd.dirty=1;gd.cpu_wait=8;}
void gd_cpu(void) BANKED {uint8_t f,t,h,goal=leader(0),bestf=255,bestt=255,besth=255;int16_t best=-32767,score;int8_t dx,dy;
/* PUBLIC decisions never read gd.traps[0]. No hidden trap avoidance, scores or inspection. */
if(!gd.placed){for(h=0;h<5;h++)for(t=0;t<49;t++)if(gd_can_play(1,h,t)){GDCard*c=gd_card(gd.inst[gd.hand[1][h]].card);score=c->kind==1?500:(c->kind==3?400:200);dx=(t%7)-(goal%7);dy=(t/7)-(goal/7);if(dx<0)dx=-dx;if(dy<0)dy=-dy;score-=dx+dy;if(score>best){best=score;besth=h;bestt=t;}}if(besth!=255){gd_play(1,besth,bestt);return;}gd.placed=1;}
best=-32767;bestt=255;for(f=0;f<49;f++)for(t=0;t<49;t++)if(gd_can_attack(1,f,t)){score=(gd.cell[t].flags&GD_LEADER)?10000:2000;if(!(gd.cell[t].flags&GD_DOWN))score+=gd_atk(gd.cell[f].iid)-gd_atk(gd.cell[t].iid);if(score>best){best=score;bestf=f;bestt=t;}}if(bestt!=255){gd_attack(1,bestf,bestt);return;}
best=-32767;bestt=255;for(f=0;f<49;f++)if(gd.cell[f].iid!=255&&gd_owner(gd.cell[f].iid)==1)for(t=0;t<49;t++)if(gd_can_move(1,f,t)){dx=(t%7)-(goal%7);dy=(t/7)-(goal/7);if(dx<0)dx=-dx;if(dy<0)dy=-dy;score=100-(dx+dy)*10;if(gd.cell[f].flags&GD_LEADER)score-=300;if(score>best){best=score;bestf=f;bestt=t;}}if(bestt!=255){gd_move(1,bestf,bestt);return;}gd_end();}
